<?php
/**
 * XXDQ i18n — create the English home / inquiry / about / contact pages.
 *
 * These pages are hand-written English (not machine-translated), so they
 * are defined here rather than generated by the translator.
 *
 * @package XXDQ
 */

$wp_root = dirname(dirname(dirname(dirname(__DIR__))));
require_once $wp_root . '/wp-load.php';

/**
 * Create or update an English page.
 *
 * @param int    $zh_id   Chinese page ID.
 * @param array  $fields  post_title / post_name / post_content / post_excerpt.
 * @param string $path    Public English path, e.g. 'inquiry/'.
 * @return int English page ID.
 */
function xxdq_make_en_page($zh_id, $fields, $path) {
    $existing = XXDQ_I18n_Content::get_en_post_id($zh_id);
    if ($existing) {
        wp_update_post([
            'ID'           => $existing,
            'post_title'   => $fields['post_title'],
            'post_content' => $fields['post_content'],
            'post_excerpt' => $fields['post_excerpt'] ?? '',
            'post_status'  => 'publish',
        ]);
        update_post_meta($existing, '_xxdq_en_slug', $fields['post_name']);
        update_post_meta($existing, '_xxdq_en_path', $path);
        /* Mirror the Chinese page's GeneratePress settings: the page
         * title is suppressed because every page renders its own hero
         * (xxdq-hero / xxdq-page-hero), the sidebar is removed and the
         * content goes full width. Without these the English home page
         * shows a stray "Home" H1 above the hero AND a right sidebar
         * that squeezes the layout — neither of which the Chinese site
         * has. */
        update_post_meta($existing, '_generate-disable-headline', 'true');
        update_post_meta($existing, '_generate-sidebar-layout-meta', 'no-sidebar');
        update_post_meta($existing, '_generate-full-width-content', 'true');
        return $existing;
    }

    $en_id = XXDQ_I18n_Content::create_en_post($zh_id, [
        'post_title'   => $fields['post_title'],
        'post_name'    => $fields['post_name'] . '-en',
        'post_content' => $fields['post_content'],
        'post_excerpt' => $fields['post_excerpt'] ?? '',
    ]);
    if (!$en_id) {
        return 0;
    }
    wp_update_post(['ID' => $en_id, 'post_status' => 'publish']);
    update_post_meta($en_id, '_xxdq_en_slug', $fields['post_name']);
    update_post_meta($en_id, '_xxdq_en_path', $path);
    update_post_meta($en_id, '_generate-disable-headline', 'true');
    update_post_meta($en_id, '_generate-sidebar-layout-meta', 'no-sidebar');
    update_post_meta($en_id, '_generate-full-width-content', 'true');
    return $en_id;
}

/* ── 1. Inquiry page (ID 17) ──────────────────────────────────── */

$inquiry_content = <<<'HTML'
<!-- wp:xxdq/inquiry-form /-->
HTML;

$en_inquiry = xxdq_make_en_page(17, [
    'post_title'   => 'Inquiry',
    'post_name'    => 'inquiry',
    'post_content' => $inquiry_content,
    'post_excerpt' => 'Send us your requirement — copper lugs, crimp terminals, pre-insulated terminals and more. We reply within 1 hour.',
], 'inquiry/');

echo "English inquiry page: {$en_inquiry}\n";

